//! Lane C vectors for `blocks/numbers/{real,setting,codes}.h`, generated by
//! `scripts/cpp_vectors/numbers_vectors.cpp`.

use core::cmp::Ordering;

use fp_core::numbers::codes::{
    at_distance, field_error, field_error_nonzero, hidden_positions, johnson, largest_m,
    mca_error, positions, rho_of, sample_error, tail_for, word_of, CodeSize, Proximity, Word,
};
use fp_core::numbers::real::{bits_of, cut2, Bound, Dir, Real, Big};
use fp_core::numbers::setting::{CountSource, Setting};

const VECTORS: &str = include_str!("../../fixtures/numbers_vectors.txt");

fn big(s: &str) -> Big {
    if s == "0" || s.is_empty() {
        Big::zero()
    } else {
        Big { w: s.split(',').map(|x| u32::from_str_radix(x, 16).unwrap()).collect() }
    }
}

fn real(s: &str) -> Real {
    let (m, e) = s.split_once('@').unwrap();
    Real { m: big(m), e: e.parse().unwrap() }
}

fn bound(s: &str) -> Bound {
    let p: Vec<&str> = s.split('|').collect();
    assert_eq!(p.len(), 3, "bound {}", s);
    Bound { lo: real(p[0]), hi: real(p[1]), bad: p[2] == "1" }
}

fn assert_bound(got: &Bound, want: &Bound) {
    assert_eq!(got.lo, want.lo, "lo");
    assert_eq!(got.hi, want.hi, "hi");
    assert_eq!(got.bad, want.bad, "bad");
}

fn setting(circle: bool) -> Setting {
    let mut s = Setting::goldilocks();
    s.circle = circle;
    s
}

fn code(log_n: u32, ell: u64, r: u64) -> CodeSize {
    CodeSize { name: String::new(), log_n, ell, r, over_e: false }
}

fn source(x: u32) -> CountSource {
    match x {
        0 => CountSource::Third,
        1 => CountSource::Johnson,
        _ => panic!("source {}", x),
    }
}

#[test]
fn number_vectors_match_the_cpp_reference() {
    let mut lines = 0usize;
    for (lineno, line) in VECTORS.lines().enumerate() {
        let t: Vec<&str> = line.split('\t').collect();
        match t[0] {
            "B" => match t[1] {
                "add" => assert_eq!(Big::add(&big(t[2]), &big(t[3])), big(t[4]), "line {}", lineno + 1),
                "mul" => assert_eq!(Big::mul(&big(t[2]), &big(t[3])), big(t[4]), "line {}", lineno + 1),
                "sub" => assert_eq!(Big::sub(&big(t[2]), &big(t[3])), big(t[4]), "line {}", lineno + 1),
                "div" => {
                    let (q, r) = Big::divmod(&big(t[2]), &big(t[3]));
                    assert_eq!(q, big(t[4]), "line {}", lineno + 1);
                    assert_eq!(r, big(t[5]), "line {}", lineno + 1);
                }
                "sqrt" => assert_eq!(Big::isqrt(&big(t[2])), big(t[3]), "line {}", lineno + 1),
                "pow" => {
                    let e: u64 = t[3].parse().unwrap();
                    assert_eq!(Big::pow(big(t[2]), e), big(t[4]), "line {}", lineno + 1);
                }
                "shl" => {
                    let n: usize = t[3].parse().unwrap();
                    assert_eq!(big(t[2]).shl(n), big(t[4]), "line {}", lineno + 1);
                }
                "shr" => {
                    let n: usize = t[3].parse().unwrap();
                    assert_eq!(big(t[2]).shr(n), big(t[4]), "line {}", lineno + 1);
                }
                "cmp" => {
                    let want = match t[4] {
                        "-1" => Ordering::Less,
                        "0" => Ordering::Equal,
                        "1" => Ordering::Greater,
                        x => panic!("cmp {}", x),
                    };
                    assert_eq!(Big::cmp(&big(t[2]), &big(t[3])), want, "line {}", lineno + 1);
                }
                "bits" => assert_eq!(big(t[2]).bits(), t[3].parse::<usize>().unwrap(), "line {}", lineno + 1),
                "any" => assert_eq!(
                    big(t[2]).any_below(t[3].parse().unwrap()),
                    t[4] == "1",
                    "line {}",
                    lineno + 1
                ),
                "tou64" => assert_eq!(big(t[2]).to_u64(), t[3].parse::<u64>().unwrap(), "line {}", lineno + 1),
                op => panic!("unknown B op {} at line {}", op, lineno + 1),
            },
            "R" => match t[1] {
                "add" | "sub" | "mul" | "div" => {
                    let a = real(t[2]);
                    let b = real(t[3]);
                    let down = real(t[4]);
                    let up = real(t[5]);
                    let (d, u) = match t[1] {
                        "add" => (Real::add(&a, &b, Dir::Down), Real::add(&a, &b, Dir::Up)),
                        "sub" => (Real::sub(&a, &b, Dir::Down), Real::sub(&a, &b, Dir::Up)),
                        "mul" => (Real::mul(&a, &b, Dir::Down), Real::mul(&a, &b, Dir::Up)),
                        _ => (Real::div(&a, &b, Dir::Down), Real::div(&a, &b, Dir::Up)),
                    };
                    assert_eq!(d, down, "line {} down", lineno + 1);
                    assert_eq!(u, up, "line {} up", lineno + 1);
                }
                "sqrt" => {
                    let a = real(t[2]);
                    assert_eq!(Real::sqrt(&a, Dir::Down), real(t[3]), "line {}", lineno + 1);
                    assert_eq!(Real::sqrt(&a, Dir::Up), real(t[4]), "line {}", lineno + 1);
                }
                "pow" => {
                    let a = real(t[2]);
                    let n: u64 = t[3].parse().unwrap();
                    assert_eq!(Real::pow(a.clone(), n, Dir::Down), real(t[4]), "line {}", lineno + 1);
                    assert_eq!(Real::pow(a, n, Dir::Up), real(t[5]), "line {}", lineno + 1);
                }
                "floor" => assert_eq!(real(t[2]).floor(), big(t[3]), "line {}", lineno + 1),
                "ceil" => assert_eq!(real(t[2]).ceil(), big(t[3]), "line {}", lineno + 1),
                "top" => assert_eq!(real(t[2]).top(), t[3].parse::<i64>().unwrap(), "line {}", lineno + 1),
                "cut2" => {
                    let a = real(t[2]);
                    let want = format!("{:.2}", cut2(bits_of(&a)));
                    assert_eq!(want, t[4], "line {}", lineno + 1);
                }
                op => panic!("unknown R op {} at line {}", op, lineno + 1),
            },
            "D" => match t[1] {
                "add" | "sub" | "mul" | "div" => {
                    let a = bound(t[2]);
                    let b = bound(t[3]);
                    let want = bound(t[4]);
                    let got = match t[1] {
                        "add" => a + b,
                        "sub" => a - b,
                        "mul" => a * b,
                        _ => a / b,
                    };
                    assert_bound(&got, &want);
                }
                "sqrt" => {
                    let a = bound(t[2]);
                    assert_bound(&Bound::sqrt(&a), &bound(t[3]));
                }
                "pow" => {
                    let a = bound(t[2]);
                    let n: u64 = t[3].parse().unwrap();
                    assert_bound(&Bound::pow(&a, n), &bound(t[4]));
                }
                "err" => {
                    let a = bound(t[2]);
                    assert_eq!(a.error(), real(t[3]), "line {}", lineno + 1);
                }
                "surely_le" => {
                    let a = bound(t[2]);
                    let b = bound(t[3]);
                    assert_eq!(fp_core::numbers::real::surely_le(&a, &b), t[4] == "1");
                }
                "surely_lt" => {
                    let a = bound(t[2]);
                    let b = bound(t[3]);
                    assert_eq!(fp_core::numbers::real::surely_lt(&a, &b), t[4] == "1");
                }
                op => panic!("unknown D op {} at line {}", op, lineno + 1),
            },
            "C" => match t[1] {
                "hidden" => {
                    let log_n: u32 = t[2].parse().unwrap();
                    let ell: u64 = t[3].parse().unwrap();
                    let r: u64 = t[4].parse().unwrap();
                    let s = setting(t[5] == "1");
                    let c = code(log_n, ell, r);
                    assert_eq!(hidden_positions(&s, &c), t[6].parse::<u64>().unwrap());
                    assert_eq!(tail_for(&s, r), t[7].parse::<u64>().unwrap());
                }
                "rho" => {
                    let log_n: u32 = t[2].parse().unwrap();
                    let ell: u64 = t[3].parse().unwrap();
                    let r: u64 = t[4].parse().unwrap();
                    let s = setting(t[5] == "1");
                    let w = word_of(&s, &code(log_n, ell, r));
                    assert_bound(&rho_of(&w), &bound(t[6]));
                }
                "johnson" => {
                    let log_n: u32 = t[2].parse().unwrap();
                    let ell: u64 = t[3].parse().unwrap();
                    let r: u64 = t[4].parse().unwrap();
                    let s = setting(t[5] == "1");
                    let m: u64 = t[6].parse().unwrap();
                    let want = Proximity {
                        agree: bound(t[7]),
                        delta: bound(t[8]),
                        eta: bound(t[9]),
                        count: bound(t[10]),
                        list: big(t[11]),
                        m,
                        from_m: true,
                        source: source(t[12].parse().unwrap()),
                    };
                    let got = johnson(&word_of(&s, &code(log_n, ell, r)), m);
                    assert_bound(&got.agree, &want.agree);
                    assert_bound(&got.delta, &want.delta);
                    assert_bound(&got.eta, &want.eta);
                    assert_bound(&got.count, &want.count);
                    assert_eq!(got.list, want.list);
                    assert_eq!(got.m, want.m);
                    assert_eq!(got.source, want.source);
                }
                "at" => {
                    let log_n: u32 = t[2].parse().unwrap();
                    let ell: u64 = t[3].parse().unwrap();
                    let r: u64 = t[4].parse().unwrap();
                    let s = setting(t[5] == "1");
                    let agree = real(t[6]);
                    let got = at_distance(&word_of(&s, &code(log_n, ell, r)), &Bound::from_real(&agree));
                    assert_bound(&got.agree, &bound(t[7]));
                    assert_bound(&got.delta, &bound(t[8]));
                    assert_bound(&got.eta, &bound(t[9]));
                    assert_bound(&got.count, &bound(t[10]));
                    assert_eq!(got.list, big(t[11]));
                    assert_eq!(got.m, t[12].parse::<u64>().unwrap());
                    assert_eq!(got.source, source(t[13].parse().unwrap()));
                }
                "mca" => {
                    // The line does not repeat the code; the preceding johnson case is the context.
                    // The tool prints one mca per johnson, in order.
                    let _ = t;
                }
                "pos" => {
                    let agree = real(t[2]);
                    let bits: u32 = t[3].parse().unwrap();
                    let extra = bound(t[4]);
                    let factor: u64 = t[5].parse().unwrap();
                    let want: u64 = t[6].parse().unwrap();
                    assert_eq!(positions(&Bound::from_real(&agree), bits, &extra, factor), want);
                }
                "fielderr" => {
                    let s = setting(false);
                    let kind: u32 = t[2].parse().unwrap();
                    let degree: u64 = t[3].parse().unwrap();
                    let got = if kind == 0 {
                        field_error(&s, degree)
                    } else {
                        field_error_nonzero(&s, degree)
                    };
                    assert_bound(&got, &bound(t[4]));
                }
                "sample" => {
                    let list = big(t[2]);
                    let cube: u32 = t[3].parse().unwrap();
                    let answers: u32 = t[4].parse().unwrap();
                    let s = setting(t[5] == "1");
                    assert_bound(&sample_error(&s, &list, cube, answers), &bound(t[6]));
                }
                "largest" => {
                    let limit: u64 = t[2].parse().unwrap();
                    assert_eq!(largest_m(|m| (5..=20).contains(&m), limit), t[3].parse::<u64>().unwrap());
                }
                op => panic!("unknown C op {} at line {}", op, lineno + 1),
            },
            other => panic!("unknown vector kind {} at line {}", other, lineno + 1),
        }
        lines += 1;
    }
    assert_eq!(lines, 3785);
}

/// The `mca` lines have their own test, because they follow their `johnson` line.
#[test]
fn mca_vectors_follow_their_johnson_case() {
    let mut last: Option<(Word, Setting)> = None;
    let mut checked = 0usize;
    for line in VECTORS.lines() {
        let t: Vec<&str> = line.split('\t').collect();
        if t[0] != "C" {
            continue;
        }
        if t[1] == "johnson" {
            let s = setting(t[5] == "1");
            let w = word_of(&s, &code(t[2].parse().unwrap(), t[3].parse().unwrap(), t[4].parse().unwrap()));
            last = Some((w, s));
        } else if t[1] == "mca" {
            let (w, s) = last.as_ref().unwrap();
            let m: u64 = t[2].parse().unwrap();
            assert_bound(&mca_error(s, &johnson(w, m)), &bound(t[3]));
            checked += 1;
        }
    }
    assert_eq!(checked, 34);
}
